-- 6. INSERCION DE DATOS: MICROCURRICULOS
INSERT OR IGNORE INTO microcurriculo (id, idasignatura, nucleo, objetivogeneral, competencias) VALUES
(1, 1, 'ECONOMIA PUBLICA', 'Dotar al estudiante de conceptos más importantes derivados de la teoría microeconomica, la intervencion del estado y la eleccion pública y social.', 'Construye argumentos solidos, con premisas y conclusiones que se construyen en forma logica. Identifica relaciones economicas causales y deduce conclusiones logicas. Elabora a partir de distintos elementos de informacion economica una lectura coherente de una situacion Toma decisiones acertadas respecto a los procesos de produccion, distribucion y consumo.'),
(2, 2, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Conocer el origen y transformacion historica del Estado, las teorías que se han desarrollado en su configuracion, los temas, problemas y relaciones existentes entre el Estado y el poder, visto desde las diversas corrientes del pensamiento contemporáneo.', 'Identifica el origen del Estado moderno y las principales teorías que se han desarrollado historicamente sobre el Estado. Define y seÃ±ala los tipos de Estado que se han formado in la historia moderna hasta nuestros días. Caracteriza los temas, problemas y relaciones existentes entre el Estado y el Régimen a partir de corrientes del pensamiento contemporáneo.'),
(3, 3, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Incorporar los conceptos fundamentales de la sociología, pertinentes a la administracion pública, en la formacion profesional de Administrador Público.', 'Explica los fundamentos sociologicos básicos y los adapta a la enseÃ±anza de la Administracion Pública. Relaciona los conceptos y escuelas sociologicas, dando una aproximacion historica y epistemologica de la Sociología como disciplina que incide en su ejercicio profesional como Administrador Público. Identifica las características de los fenomenos sociales y de las organizaciones modernas que emergen en la realidad social.'),
(4, 4, 'GESTION TERRITORIAL', 'Observar las interrelaciones entre los elementos físicos y humanos en el territorio para contribuir a la sostenibilidad ambiental a través de la planificacion territorial, el análisis del medio físico y de los impactos de la gestion pública ambiental.', 'Observa las dimensiones físicas y ambientales del territorio. Construye y aporta propuestas para contribuir a la sostenibilidad ambiental a partir del análisis de la gestion pública ambiental en Colombia.'),
(5, 5, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'A partir del análisis documental, se pretende propiciar un espacio para la reflexion individual y colectiva sobre las causas políticas economicas y socioculturales que fueron determinantes para la puesta en marcha y consolidacion de diversas formas de organizacion político-administrativas a lo largo del siglo XIX...', 'Capacidad de entender la constitucion y transformacion de la administracion pública en Colombia, evidenciando, distintos procesos historicos y pensadores que han contribuido ha dicho proposito. Comprende la estructuracion de la administracion pública como un campo de fenomenos y de saber interdependientes...'),
(6, 6, 'COMPLEMENTARIA', 'Comprender las herramientas y técnicas cuantitativas del cálculo diferencial para su aplicacion en situaciones economico -administrativas que involucren: procesos de optimizacion de una cantidad variable, análisis gráfico, razones de cambio, oferta, demanda...', 'Define una proposicion como un objeto matemático y comprende los conectores logicos como operadores que permiten realizar la combinacion de proposiciones. Analiza las relaciones entre variables de un fenomeno o proceso economico natural o social para determinar o estimar su comportamiento...'),
(7, 7, 'GESTION TERRITORIAL', 'Determinar las desigualdades territoriales desde una perspectiva global y temática, así como el papel que desempeÃ±an en la organizacion socio espacial. A partir de la introduccion de la geografía economica y social de Colombia...', 'Representa la relacion de la geografía con los sistemas de organizacion socioeconomica en el territorio. Utiliza un vocabulario geográfico, social y economico de carácter básico.'),
(8, 8, 'COMPLEMENTARIA', 'Comprender las herramientas y técnicas cuantitativas del cálculo integral para su aplicacion en situaciones economico -administrativas que involucren procesos variacionales que conlleven a la construccion de modelos mediante integrales, matrices y sistemas de ecuaciones...', 'Resuelve problemas aplicando procedimientos aritméticos, algebraicos y de la integral indefinida en el campo de la economía y la administracion, apoyado en el uso de un software de matemática. Representa e Interpreta tablas, gráficas, mapas, diagramas y textos con símbolos matemáticos...'),
(9, 9, 'ECONOMIA PUBLICA', 'Desarrollar en los estudiantes las habilidades y destrezas del análisis micro y macroeconomico y la comprension del entorno junto con la posicion crítica frente a lo que ocurre en la economía colombiana.', 'Desarrolla las habilidades y conocimientos para la adecuada interpretacion de los fenomenos economicos. Maneja los modelos desde la perspectiva racional interpretativa aplicándolos a la realidad. Identifica e internaliza el papel del Estado y su responsabilidad social en el manejo de los elementos que le conciernen al Administrador Público.'),
(10, 10, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Conocer, comprender, analizar, aplicar y evaluar los orígenes y fundamentos de los conceptos, enfoques, modelos y teorías respecto al fenomeno de lo público y la Administracion Pública desde una perspectiva historica, disciplinar y crítica...', 'Habilita el conocimiento de enfoques, modelos, estilos y tradiciones de administracion pública de diferentes países desde dos perspectivas, la historica y la actual. Incentiva la habilidad y actitud del estudiante de hacer miradas comparadas en el análisis y proyeccion de problemáticas...'),
(11, 11, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Analizar los diferentes tipos de sistemas y de regímenes políticos existentes en el mundo político actual, identificando sus procesos historicos más significativos sobre los cuales se estructura el poder político en Europa, Norteamérica, Asia y América Latina.', 'Construye una vision general sobre los distintos tipos de sistemas y de regímenes políticos existentes en el mundo. Comprende el fundamento y estructura de los sistemas y regímenes desarrollados in Europa, Norteamérica, Asia y América Latina. Contrasta los sistemas y regímenes políticos...'),
(12, 12, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Examinar el campo relativo a lo cultural: formas de interaccion entre el ser humano y su entorno, lo identitario y lo atinente a la alteridad. Enmarcado ello en la diversidad cultural y espacial, verbi gracia, territorial...', 'Comprende los conceptos y fundamentos teoricos relacionados con la identidad y diversidad cultural. Valora las otras formas de conocer-ser-hacer-interactuar con el mundo. Desarrolla sensibilidad para percibir la dimension cultural del desarrollo desde la administracion pública.'),
(13, 13, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Comprender la diversidad étnica y cultural de los actores y movimientos sociales que habitan en Colombia y que interactúan en la accion política, sus formas de autogestion y administracion étnica...', 'Reconoce la diversidad étnica y cultural de la nacion colombiana y su proceso historico. Describe el autogobierno indígena en la administracion de sus territorios. Reconoce los desafíos de la administracion pública para desarrollar procesos de gestion intercultural.'),
(14, 14, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Comprender el significado y la funcion de la constitucion en los sistemas jurídicos y políticos contemporáneos y específicamente, conocer y comprender la Constitucion Política Colombiana...', 'Comprende de conceptos jurídicos indispensables para interpretar el texto constitucional. Resuelve casos relativos a la administracion pública desde una perspectiva constitucional. Relaciona los idearios constitucionales a situaciones concretas de la vida social...'),
(15, 15, 'COMPLEMENTARIA', 'Comprender las metodologías y herramientas de la estadística descriptiva para su aplicacion investigativa en situaciones economico - administrativas que involucren obtener y procesar volúmenes de datos...', 'Interpreta tablas y gráficas de un conjunto de datos dados en una situacion particular. Comprende y aplica diferentes tipos de razonamiento, haciendo inferencias y validando argumentos útiles para la toma de decisiones...'),
(16, 16, 'ECONOMIA PUBLICA', 'Proporcionar las competencias teoricas, analíticas y prácticas suficientes sobre las finanzas públicas y su estructuracion, que permita sentar las bases para un ejercicio profesional idoneo...', 'Fundamenta la teoría y la técnica de análisis financiero de la hacienda pública colombiana. Entiende de los indicadores financieros públicos. Analiza e interpreta la informacion contable y financiera de las entidades públicas...'),
(17, 17, 'COMPLEMENTARIA', 'Apropiar la investigacion como un trabajo científico- profesional- artesanal que requiere apropiar modelos, habilidades, practicas, técnicas y valores que permitan realizarlas bajos cánones de validez.', 'Reconoce la importancia y naturaleza de la investigacion y la consultoría en la administracion pública. Apropia críticamente criterios, modelos, técnicas e instrumentos de investigacion básica y aplicada...'),
(18, 18, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Conocer, comprender, analizar y evaluar los conceptos, concepciones, teorías, tendencias, metodologías, historia, contexto, implicaciones e instrumentos de intervencion en torno a las organizaciones humanas...', 'Adquiere habilidades conceptuales y hermenéuticas para la comprension de los eventos organizacionales de la administracion pública. Argumenta en torno al fenomeno organizacional público. Fortalece rasgos comportamentales propositivos e investigativos...'),
(19, 19, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Brindar herramientas conceptuales para la comprension del territorio desde las poblaciones, su evolucion y estructura.', 'Observa el territorio con enfoque demográfico. Emplea razonamiento analítico y sintético a partir de las variables e indicadores demográficos. Sistematiza e interpreta informacion demográfica...'),
(20, 20, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Comprender la relacion existente entre los conceptos de ciudadanía y convivencia con la finalidad de formar ciudadanos participativos en la vida social y política del país...', 'Comprende los elementos centrales de la convivencia ciudadana, como: la democracia, la representacion política y la participacion ciudadana. Reconoce la diversidad social y política del país y comprende las complejidades de la convivencia...'),
(21, 21, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Comprender el concepto de Derecho y Derecho Administrativo, las formas jurídicas en que actúa el Estado, sus límites legales y relacion existente entre Estado, administracion pública y derecho administrativo...', 'Comprende el objeto y fines del derecho administrativo in Colombia. Explica los diferentes conceptos del derecho administrativo y las fases del procedimiento administrativo. Identifica las principales manifestaciones de la administracion pública...'),
(22, 22, 'COMPLEMENTARIA', 'Comprender las metodologías y herramientas de la estadística inferencial para su aplicacion investigativa que involucre inferir parámetros poblacionales a partir de una muestra...', 'Describe los estimadores de los parámetros poblaciones tomando como partida las estadísticas muestrales. Argumenta las características de las diferentes técnicas de muestreo. Identifica y aplica las técnicas y los conceptos para realizar pruebas de hipotesis...'),
(23, 23, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Conocer, comprender, analizar, aplicar y evaluar los fundamentos teoricos y técnicos de la planeacion organizacional y administrativa que permita el diseÃ±o de alternativas e instrumentos que lleven al mejoramiento...', 'Conoce, comprende y analiza los fundamentos teoricos de la Planeacion y el Análisis organizacional. Aplica y evalúa técnicas e instrumentos para la planeacion administrativa. Realiza diseÃ±os organizacionales...'),
(24, 24, 'ECONOMIA PUBLICA', 'Brindar a los estudiantes las herramientas, conceptos, procedimientos y prácticas que constituyen las Finanzas Públicas nacionales y territoriales y el presupuesto público como eje central de su financiamiento...', 'Conoce los enfoques básicos del presupuesto público y la normatividad asociada. Entiende y aplica herramientas e instrumentos de análisis y ejecucion. Analiza los actores que intervienen en los procesos políticos de decision presupuestal.'),
(25, 25, 'ECONOMIA PUBLICA', 'Dar a conocer las herramientas teoricas y prácticas que le permitan al estudiante comprender el sistema tributario in Colombia in los niveles nacional, departamental y municipal in los frentes de la economía y la gestion fiscal.', 'Aprende de la normatividad tributaria. Innova mecanismos que permitan crear cultura de gestion tributaria. DiseÃ±a políticas orientadas a la planeacion tributaria y su impacto in la Administracion Pública. Elabora estrategias fiscales que permitan optimizar los recursos y solucionar la situacion fiscal de los diferentes niveles de gobierno.'),
(26, 26, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Proporcionar conocimiento teorico práctico respecto de los fundamentos y teorías sobre Gobierno y las perspectivas e instrumentos de las Políticas Públicas como campo de estudio y dispositivo de accion gubernamental.', 'Da cuenta de los fundamentos y teorías sobre Gobierno, así como de la relacion entre Estado, Gobierno y A. P. Comprende las perspectivas de estudio de Políticas públicas... Apropia y aplica las características propias de la identificacion de problemas públicos... Comprende los elementos constitutivos y analiza con suficiencia el proceso secuencial... Establece relaciones comprensivas y analíticas entre enfoques teoricos y el abordaje de condiciones propias de la realidad colombiana...'),
(27, 27, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Estudiar, identificar y comprender la organizacion estatal colombiana, como un sistema estructurado in el que se desarrollan y se toman decisiones funcionales y de política pública.', 'Comprende la estructura organizativa del Estado colombiano de acuerdo con la constitucion y las normas más relevantes. Identifica las competencias, organos, funciones y dinámicas organizacionales del sector público colombiano. Identificara los referentes normativos y los principales problemas in torno a al régimen nacional, departamental y municipal.'),
(28, 28, 'GESTION TERRITORIAL', 'Estudiar y analizar el proceso de gobernabilidad ambiental dado in el país, a partir de los avances y retrocesos de la implementacion de políticas ambientales y de la Gestion Ambiental, mediante el cumulo de instrumentos ambientales de sustentabilidad del territorio nacional...', 'Comprende los impactos ambientales de la utilizacion de los recursos naturales que ameritan un marco de gestion institucional. Comprende las teorías y conceptos ambientales y gana sensibilidades y cultura ambiental. Innova y lidera la formulacion de propuestas para la gestion ambiental. Conoce y evalúa las políticas públicas ambientales implementadas in el país.'),
(29, 29, 'GESTION TERRITORIAL', 'Relacionar los diversos elementos de los sistemas de informacion territorial: SIG, personas, procedimientos, datos y recursos tecnologicos para resolver problemas complejos de planificacion y gestion.', 'Analiza y gestiona con eficiencia y eficacia problemas complejos de planificacion y gestion con los sistemas de informacion territorial. Emplea razonamiento analítico y sintético. Innova y lidera la formulacion de propuestas para la gestion territorial.'),
(30, 30, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Abordar el proceso de toma de decisiones y el liderazgo in el sector público desde una perspectiva científica y epistemologica y de los instrumentos para entender el fenomeno decisional in la esfera pública y política.', 'Conoce y aplica el proceso para tomar decisiones estratégicas. Comprende la importancia de la toma de decisiones in seleccion de alternativas y ejecucion de intervenciones in el sector público. Reconoce la perspectiva del liderazgo y la relacion con la cultura organizacional y los procesos de desarrollo.'),
(31, 31, 'ECONOMIA PUBLICA', 'Apropiar los elementos generales de la teoría contable para la interpretacion, análisis, aplicacion y evaluacion de los estados e informes de la contabilidad pública a través de la cual Administrador Público toma decisiones in las organizaciones públicas.', 'Diferencia los elementos afines y no afines entre la contabilidad general y la gubernamental. Conoce y aplica las normas de la Contabilidad Pública. Está in capacidad de realizar el manejo contable. Entiende y aplica el ejercicio del control fiscal.'),
(32, 32, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Analizar la contratacion pública in Colombia, sus fundamentos, principios y reglas que orientan las diferentes etapas de la actividad contractual que realizan las entidades del Estado e identificar las problemáticas que se sucintan in el proceso.', 'Identifica las características de la Contratacion Pública in Colombia. Comprende los diferentes procesos y modalidades de Seleccion de contratacion. Proyecta una contratacion pública de acuerdo con el régimen establecido.'),
(33, 33, 'GESTION TERRITORIAL', 'Conocer, analizar y discutir las decisiones públicas relacionadas con la distribucion de las funciones y las responsabilidades del Estado entre el nivel nacional y las entidades territoriales que definen y caracterizan el proceso de descentralizacion colombiano...', 'Comprende los debates sobre el proceso de descentralizacion colombiano y las discusiones sobre autonomía territorial. Reconoce los diferentes niveles de gobiernos, las entidades territoriales, sus competencias y obligaciones. Comprende y actúa in el marco de los procesos de descentralizacion y las formas de gobierno que se dan entre los distintos niveles para gestionar los asuntos públicos.'),
(34, 34, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Analizar los elementos que caracterizan la gestion de los recursos físicos in las organizaciones públicas colombianas, profundizando in el estudio de herramientas de la administracion, útiles para mejorar la gestion de estos.', 'Identifica los elementos que componen un sistema de la gerencia de recursos físicos. Identifica, clasifica y valora la importancia de los recursos físicos in la produccion de bienes y prestacion de servicios in organizaciones públicas. Gestiona el sistema de recursos físicos. Aplica los instrumentos de control y herramientas legales in el proceso de gestion de recursos públicos para realizar un manejo transparente...'),
(35, 35, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Generar conocimiento y capacidad de análisis sobre los procesos de implementacion de Políticas Públicas y proporcionar los conocimientos y habilidades suficientes respecto de los tipos e instrumentos de evaluacion de Políticas Públicas.', 'Comprende los fundamentos teorico práctico del proceso de implementacion de Políticas Públicas. Desarrolla habilidades de análisis de los distintos componentes que hacen parte del proceso de implementacion... Apropia y aplica consistentemente los distintos instrumentos de tipo cualitativo y cuantitativo para el análisis y evaluacion... Comprende los diferentes enfoques y métodos de evaluacion... Comprende y aplica sistemáticamente los instrumentos y herramientas de manejo de datos...'),
(36, 36, 'COMPLEMENTARIA', 'Desarrollar habilidades y destrezas para de procesar datos cuantitativos in administracion pública y gobierno a partir del desarrollo de algoritmos del aprendizaje automatizado, mediante la ayuda del software estadístico R.', 'Elabora, construye y evalúa modelos supervisados in Administracion Pública o áreas afines, por medio del uso del paquete CARET del software R. Reúne y procesa datos con el R de áreas de estudio... Adquiriere la capacidad para sintetizar datos cuantitativos mediante modelos no supervisados, métodos de clasificacion y agrupacion de individuos o categorías de aprendizaje.'),
(37, 37, 'GESTION TERRITORIAL', 'Conocer el funcionamiento del catastro y las innovaciones para la gestion, planeacion y ordenacion del territorio utilizando los sistemas de informacion para la georreferenciacion del territorio.', 'Conoce el funcionamiento del catastro y emplea innovaciones para la gestion, planeacion y ordenacion del territorio Innova y lidera in la formulacion de propuestas para la gestion, planeacion y ordenacion del territorio Reconoce los sistemas de informacion catastral y de georreferenciacion.'),
(38, 38, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Entender las dinámicas fronterizas como escenarios internacionales in donde los Estados se integran cooperativamente para desarrollar acuerdos economicos, políticas sociales, resolver problemáticas comunes y afianzar los lazos interestatales para gestionar multilateralmente la vida regional fronteriza.', 'Comprende las teorías de frontera y de las relaciones internacionales Relaciona la economía nacional con la economía internacional in relacion con la integracion multinacional Identifica los problemas fronterizos que tiene Colombia con los países vecinos y plantea posibles soluciones Reconoce el derecho internacional como mecanismo para dirimir las diferencias entre los Estados'),
(39, 39, 'COMPLEMENTARIA', 'Ofrecer a los estudiantes una introduccion a los conceptos básicos, los métodos y las técnicas de la investigacion cualitativa, como complemento de la investigacion cuantitativa, para la interpretacion de los comportamientos de las personas in ambientes cotidianos y su relacion con el éxito de las decisiones in la administracion pública.', 'Comprende la importancia de los métodos cualitativos in la investigacion social Aplica las técnicas de gestion de datos cualitativos in el ámbito de la administracion pública y la toma de decisiones Interpreta datos obtenidos mediante técnicas cualitativas.'),
(40, 40, 'GESTION TERRITORIAL', 'Brindar herramientas e instrumentos desde lo legal y lo legítimo para entender la organizacion territorial del Estado colombiano y las problemáticas relacionadas con el territorio, la territorializacion, así como las dinámicas in la construccion y deconstruccion del territorio.', 'Comprende la organizacion territorial político administrativa del Estado colombiano y las problemáticas relacionadas Comprende los mecanismos y formas de asociacion de las entidades territoriales para solucionar problemas comunes Aporta in la formulacion de propuestas para transformar las problemáticas relacionadas con la organizacion territorial.'),
(41, 41, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Identificar, describir, analizar, interpretar y evaluar el estado actual del control de la gestion a partir de las experiencias exitosas y problemáticas de las entidades del Estado para proponer recomendaciones para su fortalecimiento.', 'Comprende los objetivos y limitaciones del control de gestion abordado desde el paradigma de la simplicidad in la Administracion Pública in Colombia. Identifica los tipos y modelos de controle establecidos in la CP 1991 y el marco normativo, así como su aporte al cumplimiento de los objetivos in las entidades del Estado. Caracteriza los entes de control in Colombia, sus funciones y aportes para el cumplimiento de los fines del Estado. DiseÃ±a, desarrolla e interpreta un sistema integral de medicion de la gestion a partir de indicadores propuestos para monitorear la gestion in una entidad.'),
(42, 42, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Conocer, comprender, analizar, aplicar y evaluar los fundamentos teoricos, las técnicas, los instrumentos y las técnicas, así como desarrollar las competencias indispensables para el éxito in la gerencia de recursos humanos in el ámbito de la administracion pública', 'Interpreta, conoce, reflexiona el marco normativo y de praxis del talento humano público Direcciona, planifica y desarrolla el capital humano. Conoce las formas de ingreso, permanencia, desarrollo y retiro de la funcion administrativa. Valora los sistemas de concurso, las normas de transparencia, capacitacion, evaluacion y del clima laboral in la organizacion pública.'),
(43, 43, 'ECONOMIA PUBLICA', 'Comprender y aplicar los mecanismos, técnicas y procedimientos para la identificacion, formulacion y auditoria de proyectos de desarrollo, como medio para la efectiva aplicacion de recursos públicos apropiados para la satisfaccion de necesidades colectivas.', 'Conoce el proceso de formulacion y evaluacion de proyectos de desarrollo. Establece la pertinencia, impactos y beneficios de la puesta in accion de los proyectos de desarrollo Maneja y domina de manera teorico-práctica las metodologías y técnicas de la formulacion y evaluacion de proyectos de desarrollo.'),
(44, 44, 'ECONOMIA PÚBLICA', 'Formar a los estudiantes para que distingan la correlacion entre derechos y servicios, así como in los conceptos de estudios tarifarios, subsidios y contribuciones de solidaridad social, con el ánimo de que a través de los diferentes roles administrativos contribuyan in la modernizacion del Estado y de sus instituciones in el marco de la consolidacion de los procesos de descentralizacion por servicios.', 'Comprende la teoría economica y jurídica del servicio público Conoce y aplica los enfoques y conceptos de la gestion de los servicios públicos (planeacion, organizacion, seguimiento, evaluacion y control. Es capaz de establecer estrategias de mejora organizativa y aseguramiento de la calidad de los servicios públicos territoriales. Genera procesos de creacion, fusion y escision de organizaciones proveedoras de servicios públicos para adecuarlas a los momentos políticos, sociales y economicos del Estado'),
(45, 45, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Conocer, comprender, analizar y evaluar el marco conceptual y normativo que rige el funcionamiento de la funcion pública, el régimen jurídico del Servidor Público y la accion de los servidores públicos y la realidad de la administracion del personal al servicio del Estado in Colombia y su expresion más desarrollada como es la carrera administrativa.', 'Entiende y aplica el régimen público asociado con el servicio y la funcion pública Comprende el régimen penal y de derecho administrativo laboral Promueve con conocimientos y actitudes los sistemas de control y programas de moralizacion in el sector público'),
(46, 46, 'GESTION TERRITORIAL', 'Conocer los conceptos y las problemáticas que conduzcan a la comprension de la construccion territorial desde su integralidad in los procesos de toma de decision para la gestion pública', 'Comprende integralmente la construccion territorial y los instrumentos para gestionar con eficiencia y eficacia los recursos de las entidades territoriales Analiza e implementa políticas con una lectura holística del territorio, para una gestion efectiva de los gobiernos locales'),
(47, 47, 'GESTION TERRITORIAL', 'Identificar los principales conceptos y las herramientas vinculadas al ordenamiento territorial que permiten aplicar los objetivos definidos in los planes y políticas de ordenamiento territorial.', 'Maneja los principales conceptos y las herramientas vinculadas a los planes y políticas de ordenamiento territorial Conoce el marco legal e institucional de la gestion pública colombiana in el ámbito nacional y territorial para la toma de decisiones Reconoce la importancia del ordenamiento territorial in los procesos de desarrollo territorial'),
(48, 48, 'ESTADO, GOBIERNO Y SOCIEDAD', 'Dilucidar los aspectos fundamentales y procedimentales de la práctica disciplinaria dentro del ejercicio de la administracion pública, para comprender las formas, aplicacion y ejecucion de la normatividad disciplinaria y se prevenga o castigue los delitos in contra de la funcion pública y la administracion pública.', 'Explica los fundamentos y teorías del régimen disciplinario in Colombia Sintetiza la estructura del proceso disciplinario in Colombia Identifica claramente las faltas o delitos contra la administracion pública Determina los pasos procedimentales que se efectúan in una investigacion disciplinar hasta su cierre.'),
(49, 49, 'COMPLEMENTARIA', 'Desarrollar habilidades y destrezas para procesamiento y visualizacion de datos cuantitativos para pequeÃ±as y grandes bases de datos in administracion pública.', 'Elabora y construye visualizaciones in Administracion Pública o áreas afines, por medio del uso de herramientas de Excel, el software R o Python Reúne y procesa datos de datos con el R, para emitir juicios que incluyan una reflexion sobre temas relevantes de índole social, economico y científico in AP, desde la visualizacion de datos Visualiza datos cuantitativos mediante las herramientas vistas in el curso y otras que el estudiante encuentre Interpreta resultados del análisis de datos e informacion abierta para llegar a tomar decisiones correctas.'),
(51, 51, 'GESTION TERRITORIAL', 'Conocer los antecedentes, el marco legal y metodologico para la planeacion del desarrollo territorial in Colombia', 'Comprende los antecedentes, marco legal y metodologico para la planeacion del desarrollo territorial in Colombia Innova y lidera in la formulacion de propuestas, planes, programas y proyectos para mejorar la toma de decisiones para el cumplimiento de los fines del Estado in el ámbito territorial.'),
(54, 54, 'ORGANIZACIONES PÚBLICAS Y GESTION', 'Aproximar a los estudiantes al conocimiento de los marcos conceptuales, las técnicas y herramientas propuestas por las ciencias de la gestion, para el mejoramiento de la capacidad institucional de las organizaciones públicas con el fin de que sirvan de marco referencial para verificar y comparar su existencia, aplicacion y desarrollo in las entidades y organismos del Estado Colombiano.', 'Comprende las características, técnicas y herramientas de los nuevos enfoques y modelos de la Administracion Pública Gestiona las entidades públicas locales, territoriales, nacionales o sociales, aplicando herramientas de calidad, servicios, trámites, atencion al usuario y sistemas de administracion contemporánea. Entiende, aplica y promueve esquemas de transparencia y lucha anticorrupcion, a partir de la aplicacion de nuevos conceptos y herramientas de gerencia pública.');

